package jp.wakeguard.alarm;

import android.app.*;
import android.content.*;
import android.media.*;
import android.net.Uri;
import android.os.*;

/** Plays timer completion audio independently of notification-channel sound settings. */
public class TimerRingService extends Service {
    public static final String ACTION_START="jp.wakeguard.alarm.TIMER_RING_START",ACTION_STOP="jp.wakeguard.alarm.TIMER_RING_STOP",ACTION_SILENCE="jp.wakeguard.alarm.TIMER_RING_SILENCE",ACTION_RESUME="jp.wakeguard.alarm.TIMER_RING_RESUME";
    private static final String CHANNEL="wakeguard_timer_ring_v3"; private static final int NOTIFY=118001;
    private MediaPlayer player;private ToneGenerator fallback;private Handler toneHandler;private Vibrator vibrator;private PowerManager.WakeLock wakeLock;
    private String currentUri="",currentLabel="",currentMediaName="";private long currentTimerId=-1L;private boolean currentVideo=false;private Handler videoDelayHandler;private boolean timerVideoReady=false;
    public static boolean start(Context c,TimerStore.Entry e){if(e==null)return false;Intent i=new Intent(c,TimerRingService.class).setAction(ACTION_START).putExtra("timerId",e.id).putExtra("label",e.label==null?"":e.label).putExtra("soundUri",e.soundUri==null?"":e.soundUri).putExtra("mediaName",e.soundName==null?"":e.soundName);try{if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);return true;}catch(Throwable ignored){return false;}}
    @Override public void onCreate(){super.onCreate();ensureChannel();toneHandler=new Handler(Looper.getMainLooper());videoDelayHandler=new Handler(Looper.getMainLooper());}
    @Override public int onStartCommand(Intent i,int flags,int startId){if(i!=null&&ACTION_STOP.equals(i.getAction())){stopRing();return START_NOT_STICKY;}if(i!=null&&ACTION_SILENCE.equals(i.getAction())){timerVideoReady=true;cancelVideoDelay();stopServiceAudioOnly();stopVibrationOnly();return START_NOT_STICKY;}if(i!=null&&ACTION_RESUME.equals(i.getAction())){timerVideoReady=false;cancelVideoDelay();if(currentVideo)startVideoFallbackNow();else startOutputs(currentUri,false);return START_NOT_STICKY;}String label=i==null?"":i.getStringExtra("label");String uri=i==null?"":i.getStringExtra("soundUri");String mediaName=i==null?"":i.getStringExtra("mediaName");currentTimerId=i==null?-1L:i.getLongExtra("timerId",-1L);currentLabel=label==null?"":label;currentUri=uri==null?"":uri;currentMediaName=mediaName==null?"":mediaName;currentVideo=isVideoUri(currentUri,currentMediaName);timerVideoReady=false;startForeground(NOTIFY,buildNotification(currentTimerId,currentLabel,currentUri,currentMediaName));startOutputs(currentUri,currentVideo);return START_NOT_STICKY;}
    private Notification buildNotification(long timerId,String label,String uri,String mediaName){String title=(label==null||label.trim().isEmpty())?I18n.tr(this,"タイマー終了"):label.trim();boolean video=isVideoUri(uri,mediaName);int request=118100+(int)Math.floorMod(timerId,1000000L);Intent open=video?new Intent(this,TimerVideoActivity.class).setData(Uri.parse("wakeguard://timer/"+timerId+"/ring")).putExtra("videoUri",uri).putExtra("label",title).putExtra("timerId",timerId):new Intent(this,ClockActivity.class).putExtra("mode","timer");open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent openPi;if(Build.VERSION.SDK_INT>=34){ActivityOptions creator=ActivityOptions.makeBasic();creator.setPendingIntentCreatorBackgroundActivityStartMode(Build.VERSION.SDK_INT>=36?ActivityOptions.MODE_BACKGROUND_ACTIVITY_START_ALLOW_ALWAYS:ActivityOptions.MODE_BACKGROUND_ACTIVITY_START_ALLOWED);openPi=PendingIntent.getActivity(this,request,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE,creator.toBundle());}else openPi=PendingIntent.getActivity(this,request,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent stop=new Intent(this,TimerRingService.class).setAction(ACTION_STOP).putExtra("timerId",timerId);PendingIntent stopPi=PendingIntent.getService(this,request+1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);b.setSmallIcon(R.drawable.ic_ignido_notification).setContentTitle(title).setContentText(I18n.tr(this,video?"タップして動画を再生":"設定した時間になりました")).setCategory(Notification.CATEGORY_ALARM).setVisibility(Notification.VISIBILITY_PUBLIC).setPriority(Notification.PRIORITY_MAX).setOngoing(true).setContentIntent(openPi).addAction(new Notification.Action.Builder(null,I18n.tr(this,"タイマーを停止"),stopPi).build());if(video)b.setFullScreenIntent(openPi,true);return b.build();}
    private void ensureChannel(){if(Build.VERSION.SDK_INT<26)return;NotificationManager nm=getSystemService(NotificationManager.class);if(nm==null)return;NotificationChannel ch=new NotificationChannel(CHANNEL,I18n.tr(this,"タイマー終了"),NotificationManager.IMPORTANCE_HIGH);ch.setDescription(I18n.tr(this,"IGNIDO Wakeのタイマー終了音"));ch.setSound(null,null);ch.enableVibration(false);ch.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);nm.createNotificationChannel(ch);}
    private void startOutputs(String custom,boolean video){
        stopOutputs();acquireRingWakeLock();startRingVibration();
        if(video){timerVideoReady=false;scheduleVideoDelay();return;}
        startAudioNow(custom);
    }
    private void acquireRingWakeLock(){try{if(wakeLock!=null&&wakeLock.isHeld())return;PowerManager pm=getSystemService(PowerManager.class);if(pm!=null){wakeLock=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"WakeGuard:TimerRing");wakeLock.setReferenceCounted(false);wakeLock.acquire(30*60*1000L);}}catch(Throwable ignored){}}
    private void startRingVibration(){try{if(vibrator!=null)return;vibrator=getSystemService(Vibrator.class);if(vibrator!=null&&vibrator.hasVibrator()){long[] pattern={0,700,250,700,250,1200};if(Build.VERSION.SDK_INT>=26)vibrator.vibrate(VibrationEffect.createWaveform(pattern,0));else vibrator.vibrate(pattern,0);}}catch(Throwable ignored){}}
    private void stopVibrationOnly(){if(vibrator!=null){try{vibrator.cancel();}catch(Throwable ignored){}vibrator=null;}}
    private void startAudioNow(String custom){Uri u=null;try{if(custom!=null&&!custom.isEmpty())u=custom.startsWith("/")?Uri.fromFile(new java.io.File(custom)):Uri.parse(custom);}catch(Throwable ignored){}if(u==null)u=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);player=createPlayer(u);if(player==null)player=createPlayer(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM));boolean playing=false;try{playing=player!=null&&player.isPlaying();}catch(Throwable ignored){}if(!playing)startFallback();}
    private void stopServiceAudioOnly(){if(player!=null){try{player.stop();}catch(Throwable ignored){}try{player.release();}catch(Throwable ignored){}player=null;}if(fallback!=null){try{fallback.stopTone();fallback.release();}catch(Throwable ignored){}fallback=null;}if(toneHandler!=null)toneHandler.removeCallbacksAndMessages(null);}
    private void cancelVideoDelay(){try{if(videoDelayHandler!=null)videoDelayHandler.removeCallbacksAndMessages(null);}catch(Throwable ignored){}}
    private void scheduleVideoDelay(){cancelVideoDelay();if(videoDelayHandler==null)videoDelayHandler=new Handler(Looper.getMainLooper());videoDelayHandler.postDelayed(()->{if(currentVideo&&!timerVideoReady)startVideoFallbackNow();},1800L);}
    private void startVideoFallbackNow(){cancelVideoDelay();if(timerVideoReady)return;stopServiceAudioOnly();acquireRingWakeLock();startRingVibration();startAudioNow(currentUri);}
    private boolean isVideoUri(String raw,String name){if(raw!=null&&!raw.trim().isEmpty()){try{String type=getContentResolver().getType(Uri.parse(raw));if(type!=null&&type.toLowerCase(java.util.Locale.ROOT).startsWith("video/"))return true;}catch(Throwable ignored){}String x=raw.toLowerCase(java.util.Locale.ROOT);if(x.endsWith(".mp4")||x.endsWith(".m4v")||x.endsWith(".3gp")||x.endsWith(".3gpp")||x.endsWith(".webm")||x.endsWith(".mkv")||x.endsWith(".ts"))return true;}String n=name==null?"":name.toLowerCase(java.util.Locale.ROOT);return n.endsWith(".mp4")||n.endsWith(".m4v")||n.endsWith(".3gp")||n.endsWith(".3gpp")||n.endsWith(".webm")||n.endsWith(".mkv")||n.endsWith(".ts");}
    private MediaPlayer createPlayer(Uri u){if(u==null)return null;MediaPlayer m=new MediaPlayer();try{m.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());m.setDataSource(this,u);m.setLooping(true);m.prepare();m.start();return m;}catch(Throwable t){try{m.release();}catch(Throwable ignored){}return null;}}
    private void startFallback(){try{fallback=new ToneGenerator(AudioManager.STREAM_ALARM,100);Runnable[] r=new Runnable[1];r[0]=()->{if(fallback==null)return;try{fallback.startTone(ToneGenerator.TONE_CDMA_ALERT_CALL_GUARD,900);}catch(Throwable ignored){}toneHandler.postDelayed(r[0],1300L);};toneHandler.post(r[0]);}catch(Throwable ignored){}}
    private void stopOutputs(){stopServiceAudioOnly();cancelVideoDelay();timerVideoReady=false;stopVibrationOnly();if(wakeLock!=null){try{if(wakeLock.isHeld())wakeLock.release();}catch(Throwable ignored){}wakeLock=null;}}
    private void stopRing(){stopOutputs();try{stopForeground(STOP_FOREGROUND_REMOVE);}catch(Throwable ignored){}stopSelf();}
    @Override public void onDestroy(){stopOutputs();super.onDestroy();}
    @Override public android.os.IBinder onBind(Intent i){return null;}
}
